import 'server-only';
import { cookies } from 'next/headers';

if (!global.dashboardSessions) {
  global.dashboardSessions = new Map();
}

const sessions = global.dashboardSessions;

export async function getSession() {
  const cookieStore = await cookies();

  const sessionId = cookieStore.get('dashboard_session')?.value;

  if (!sessionId) {
    console.log('[AUTH] No dashboard_session cookie');
    return null;
  }

  const session = sessions.get(sessionId);

  if (!session) {
    console.log('[AUTH] Session not found');
    return null;
  }

  if (session.expiresAt && session.expiresAt < Date.now()) {
    console.log('[AUTH] Session expired');

    sessions.delete(sessionId);

    return null;
  }

  return session;
}

export async function isOwner() {
  const session = await getSession();

  if (!session) {
    console.log('[AUTH] No session');
    return false;
  }

  const ownerRoleId = process.env.OWNER_ROLE_ID;

  if (!ownerRoleId) {
    console.error('[AUTH] OWNER_ROLE_ID is missing from environment');
    return false;
  }

  const roles = Array.isArray(session.roleIds)
    ? session.roleIds
    : [];

  const owner = roles.includes(ownerRoleId);

  console.log('[AUTH] Owner check:', {
    userId: session.user?.id,
    roleCount: roles.length,
    ownerRoleId,
    owner,
  });

  return owner;
}